package edu.alliance.medislot.dao;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.sql.Timestamp;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.UUID;

/** JDBC persistence for prescriptions, the medicine storefront, queue tokens, and reminders. */
public final class Phase45Dao {
    public List<Map<String,Object>> catalog(String query) throws SQLException {
        String sql = "SELECT id,name,category,price,stock FROM medicines WHERE stock>0 AND (?='' OR LOWER(name) LIKE ? OR LOWER(category) LIKE ?) ORDER BY name";
        List<Map<String,Object>> rows = new ArrayList<>();
        String term = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
        try (Connection c=Database.getConnection(); PreparedStatement p=c.prepareStatement(sql)) {
            p.setString(1,term); p.setString(2,"%"+term+"%"); p.setString(3,"%"+term+"%");
            try(ResultSet r=p.executeQuery()){ while(r.next()){ Map<String,Object> m=new LinkedHashMap<>(); m.put("id",r.getLong("id"));m.put("name",r.getString("name"));m.put("category",r.getString("category"));m.put("price",r.getBigDecimal("price"));m.put("stock",r.getInt("stock"));rows.add(m); } }
        }
        return rows;
    }

    public List<Map<String,Object>> cart(long patientId) throws SQLException {
        ensureCart(patientId); List<Map<String,Object>> rows=new ArrayList<>();
        String sql="SELECT ci.medicine_id,ci.quantity,m.name,m.category,m.price,m.stock,(m.price*ci.quantity) line_total FROM cart_items ci JOIN patient_carts c ON c.id=ci.cart_id JOIN medicines m ON m.id=ci.medicine_id WHERE c.patient_id=? ORDER BY m.name";
        try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,patientId);try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();m.put("medicineId",r.getLong("medicine_id"));m.put("name",r.getString("name"));m.put("category",r.getString("category"));m.put("quantity",r.getInt("quantity"));m.put("price",r.getBigDecimal("price"));m.put("stock",r.getInt("stock"));m.put("lineTotal",r.getBigDecimal("line_total"));rows.add(m);}}}return rows;
    }

    public void addToCart(long patientId,long medicineId,int quantity) throws SQLException {
        try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{
            long cartId=ensureCart(c,patientId);
            try(PreparedStatement p=c.prepareStatement("SELECT stock FROM medicines WHERE id=? FOR UPDATE")){p.setLong(1,medicineId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new NoSuchElementException("Medicine was not found.");if(r.getInt(1)<quantity)throw new IllegalArgumentException("Requested quantity exceeds available stock.");}}
            try(PreparedStatement p=c.prepareStatement("SELECT quantity FROM cart_items WHERE cart_id=? AND medicine_id=? FOR UPDATE")){p.setLong(1,cartId);p.setLong(2,medicineId);try(ResultSet r=p.executeQuery()){if(r.next()){int newQty=r.getInt(1)+quantity;if(newQty>100)throw new IllegalArgumentException("Cart quantity cannot exceed 100.");if(newQty>medicineStock(c,medicineId))throw new IllegalArgumentException("Requested cart quantity exceeds available stock.");try(PreparedStatement u=c.prepareStatement("UPDATE cart_items SET quantity=? WHERE cart_id=? AND medicine_id=?")){u.setInt(1,newQty);u.setLong(2,cartId);u.setLong(3,medicineId);u.executeUpdate();}}else try(PreparedStatement i=c.prepareStatement("INSERT INTO cart_items(cart_id,medicine_id,quantity) VALUES(?,?,?)")){i.setLong(1,cartId);i.setLong(2,medicineId);i.setInt(3,quantity);i.executeUpdate();}}}
            c.commit();
        }catch(SQLException|RuntimeException e){c.rollback();throw e;}}
    }

    public void removeFromCart(long patientId,long medicineId) throws SQLException {try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM cart_items WHERE medicine_id=? AND cart_id=(SELECT id FROM patient_carts WHERE patient_id=?)")){p.setLong(1,medicineId);p.setLong(2,patientId);p.executeUpdate();}}

    public Map<String,Object> checkout(long patientId) throws SQLException {
        try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{
            long cartId=ensureCart(c,patientId);String sql="SELECT ci.medicine_id,ci.quantity,m.name,m.price,m.stock FROM cart_items ci JOIN medicines m ON m.id=ci.medicine_id WHERE ci.cart_id=? ORDER BY ci.medicine_id FOR UPDATE";
            List<OrderLine> lines=new ArrayList<>();BigDecimal total=BigDecimal.ZERO;
            try(PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,cartId);try(ResultSet r=p.executeQuery()){while(r.next()){int qty=r.getInt("quantity");int stock=r.getInt("stock");BigDecimal price=r.getBigDecimal("price");if(qty>stock)throw new IllegalArgumentException("Stock changed for "+r.getString("name")+"; adjust your cart.");if(price==null||price.signum()<0)throw new SQLException("Invalid catalog price.");lines.add(new OrderLine(r.getLong("medicine_id"),r.getString("name"),qty,price));total=total.add(price.multiply(BigDecimal.valueOf(qty)));}}}
            if(lines.isEmpty())throw new IllegalArgumentException("Your cart is empty.");
            long orderId;String number;
            try(PreparedStatement p=c.prepareStatement("INSERT INTO medicine_orders(patient_id,order_number,total,status) VALUES(?,?,?,'PLACED')",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,patientId);p.setString(2,UUID.randomUUID().toString().replace("-",""));p.setBigDecimal(3,total);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(!r.next())throw new SQLException("Order id missing.");orderId=r.getLong(1);number="MO-"+String.format(Locale.ROOT,"%08d",orderId);}}
            try(PreparedStatement p=c.prepareStatement("UPDATE medicine_orders SET order_number=? WHERE id=?")){p.setString(1,number);p.setLong(2,orderId);p.executeUpdate();}
            for(OrderLine line:lines){try(PreparedStatement u=c.prepareStatement("UPDATE medicines SET stock=stock-? WHERE id=? AND stock>=?")){u.setInt(1,line.quantity);u.setLong(2,line.medicineId);u.setInt(3,line.quantity);if(u.executeUpdate()!=1)throw new IllegalArgumentException("Stock changed during checkout; please retry.");}try(PreparedStatement i=c.prepareStatement("INSERT INTO medicine_order_items(order_id,medicine_id,medicine_name,unit_price,quantity) VALUES(?,?,?,?,?)")){i.setLong(1,orderId);i.setLong(2,line.medicineId);i.setString(3,line.name);i.setBigDecimal(4,line.price);i.setInt(5,line.quantity);i.executeUpdate();}}
            try(PreparedStatement d=c.prepareStatement("DELETE FROM cart_items WHERE cart_id=?")){d.setLong(1,cartId);d.executeUpdate();}c.commit();return order(orderId);
        }catch(SQLException|RuntimeException e){c.rollback();throw e;}}
    }

    public List<Map<String,Object>> orders(long actorId,String role) throws SQLException {List<Map<String,Object>> out=new ArrayList<>();String sql="SELECT id,patient_id,order_number,total,status,created_at FROM medicine_orders"+("ADMIN".equals(role)?" ORDER BY created_at DESC":" WHERE patient_id=? ORDER BY created_at DESC");try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql)){if(!"ADMIN".equals(role))p.setLong(1,actorId);try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> row=orderRow(r);row.put("items",orderItems(c,r.getLong("id")));out.add(row);}}}return out;}

    public Map<String,Object> setOrderStatus(long orderId,String status) throws SQLException {if(!List.of("PACKED","READY","COMPLETED","CANCELLED").contains(status))throw new IllegalArgumentException("Unsupported order status.");try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{String current;try(PreparedStatement q=c.prepareStatement("SELECT status FROM medicine_orders WHERE id=? FOR UPDATE")){q.setLong(1,orderId);try(ResultSet r=q.executeQuery()){if(!r.next())throw new NoSuchElementException("Order was not found.");current=r.getString(1);}}boolean allowed=("PLACED".equals(current)&&List.of("PACKED","CANCELLED").contains(status))||("PACKED".equals(current)&&List.of("READY","CANCELLED").contains(status))||("READY".equals(current)&&List.of("COMPLETED","CANCELLED").contains(status));if(!allowed)throw new IllegalArgumentException("That order status transition is not allowed.");if("CANCELLED".equals(status)){try(PreparedStatement q=c.prepareStatement("SELECT medicine_id,quantity FROM medicine_order_items WHERE order_id=? AND medicine_id IS NOT NULL")){q.setLong(1,orderId);try(ResultSet r=q.executeQuery()){while(r.next()){try(PreparedStatement u=c.prepareStatement("UPDATE medicines SET stock=stock+? WHERE id=?")){u.setInt(1,r.getInt("quantity"));u.setLong(2,r.getLong("medicine_id"));u.executeUpdate();}}}}}try(PreparedStatement p=c.prepareStatement("UPDATE medicine_orders SET status=? WHERE id=?")){p.setString(1,status);p.setLong(2,orderId);p.executeUpdate();}c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}}return order(orderId);}

    public Map<String,Object> createPrescription(long doctorId,long appointmentId,String instructions,List<PrescriptionLine> items) throws SQLException {
        if(items.isEmpty()||items.size()>20)throw new IllegalArgumentException("Add between 1 and 20 prescription items.");
        try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{long patientId;
            try(PreparedStatement p=c.prepareStatement("SELECT a.patient_id,a.doctor_id,a.status FROM appointments a JOIN consultations x ON x.appointment_id=a.id WHERE a.id=? FOR UPDATE")){p.setLong(1,appointmentId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new NoSuchElementException("Completed appointment was not found.");if(r.getLong("doctor_id")!=doctorId)throw new SecurityException("Only the assigned doctor may prescribe for this visit.");if(!"COMPLETED".equals(r.getString("status")))throw new IllegalArgumentException("Complete the appointment before prescribing.");patientId=r.getLong("patient_id");}}
            long id;try(PreparedStatement p=c.prepareStatement("INSERT INTO prescriptions(appointment_id,patient_id,doctor_id,instructions) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,appointmentId);p.setLong(2,patientId);p.setLong(3,doctorId);p.setString(4,instructions);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(!r.next())throw new SQLException("Prescription id missing.");id=r.getLong(1);}}
            for(PrescriptionLine line:items){String name;Long medicineId=null;if(line.medicineId>0){try(PreparedStatement p=c.prepareStatement("SELECT name FROM medicines WHERE id=?")){p.setLong(1,line.medicineId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Prescription catalog medicine was not found.");name=r.getString(1);medicineId=line.medicineId;}}}else{name=line.name;}
                try(PreparedStatement p=c.prepareStatement("INSERT INTO prescription_items(prescription_id,medicine_id,medicine_name,dosage,quantity) VALUES(?,?,?,?,?)")){p.setLong(1,id);if(medicineId==null)p.setNull(2,java.sql.Types.BIGINT);else p.setLong(2,medicineId);p.setString(3,name);p.setString(4,line.dosage);p.setInt(5,line.quantity);p.executeUpdate();}}
            c.commit();return prescription(id,doctorId,"DOCTOR");
        }catch(SQLException|RuntimeException e){c.rollback();throw e;}}
    }

    public List<Map<String,Object>> prescriptions(long actorId,String role) throws SQLException {String sql="SELECT id FROM prescriptions"+("PATIENT".equals(role)?" WHERE patient_id=?":"DOCTOR".equals(role)?" WHERE doctor_id=?":"")+" ORDER BY created_at DESC";List<Map<String,Object>> rows=new ArrayList<>();try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql)){if(!"ADMIN".equals(role))p.setLong(1,actorId);try(ResultSet r=p.executeQuery()){while(r.next())rows.add(prescription(r.getLong(1),actorId,role));}}return rows;}
    public Map<String,Object> prescription(long id,long actorId,String role) throws SQLException {try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT p.id,p.appointment_id,p.patient_id,p.doctor_id,p.instructions,p.created_at,u.name patient_name,d.name doctor_name FROM prescriptions p JOIN users u ON u.id=p.patient_id JOIN users d ON d.id=p.doctor_id WHERE p.id=? AND (?='ADMIN' OR (?='PATIENT' AND p.patient_id=?) OR (?='DOCTOR' AND p.doctor_id=?))")){p.setLong(1,id);p.setString(2,role);p.setString(3,role);p.setLong(4,actorId);p.setString(5,role);p.setLong(6,actorId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new NoSuchElementException("Prescription was not found.");Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getLong("id"));m.put("appointmentId",r.getLong("appointment_id"));m.put("patientName",r.getString("patient_name"));m.put("doctorName",r.getString("doctor_name"));m.put("instructions",r.getString("instructions"));m.put("createdAt",r.getTimestamp("created_at").toLocalDateTime().toString());m.put("items",prescriptionItems(c,id));return m;}}}

    public Map<String,Object> addPrescriptionToCart(long patientId,long prescriptionId) throws SQLException {Map<String,Object> rx=prescription(prescriptionId,patientId,"PATIENT");try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{long cartId=ensureCart(c,patientId);try(PreparedStatement p=c.prepareStatement("SELECT medicine_id,quantity FROM prescription_items WHERE prescription_id=? AND medicine_id IS NOT NULL ORDER BY medicine_id")){p.setLong(1,prescriptionId);try(ResultSet r=p.executeQuery()){while(r.next()){long medicineId=r.getLong(1);int qty=r.getInt(2);int stock;try(PreparedStatement q=c.prepareStatement("SELECT stock FROM medicines WHERE id=? FOR UPDATE")){q.setLong(1,medicineId);try(ResultSet x=q.executeQuery()){if(!x.next())throw new NoSuchElementException("Prescription medicine is no longer available.");stock=x.getInt(1);}}int existing=0;try(PreparedStatement q=c.prepareStatement("SELECT quantity FROM cart_items WHERE cart_id=? AND medicine_id=? FOR UPDATE")){q.setLong(1,cartId);q.setLong(2,medicineId);try(ResultSet x=q.executeQuery()){if(x.next())existing=x.getInt(1);}}if(existing+qty>stock||existing+qty>100)throw new IllegalArgumentException("Prescription quantity exceeds available stock; cart was not changed.");if(existing==0){try(PreparedStatement i=c.prepareStatement("INSERT INTO cart_items(cart_id,medicine_id,quantity) VALUES(?,?,?)")){i.setLong(1,cartId);i.setLong(2,medicineId);i.setInt(3,qty);i.executeUpdate();}}else try(PreparedStatement u=c.prepareStatement("UPDATE cart_items SET quantity=? WHERE cart_id=? AND medicine_id=?")){u.setInt(1,existing+qty);u.setLong(2,cartId);u.setLong(3,medicineId);u.executeUpdate();}}}}c.commit();return rx;}catch(SQLException|RuntimeException e){c.rollback();throw e;}}}

    public Map<String,Object> issueQueueToken(long patientId,long appointmentId) throws SQLException {try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{long doctorId;LocalDate date;try(PreparedStatement p=c.prepareStatement("SELECT doctor_id,appointment_date,status FROM appointments WHERE id=? AND patient_id=? FOR UPDATE")){p.setLong(1,appointmentId);p.setLong(2,patientId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new NoSuchElementException("Your appointment was not found.");doctorId=r.getLong(1);date=r.getDate(2).toLocalDate();if(!"BOOKED".equals(r.getString(3))||!date.equals(LocalDate.now()))throw new IllegalArgumentException("Queue tokens are available only for today's booked appointments.");}}
            long id;try(PreparedStatement p=c.prepareStatement("INSERT INTO queue_tokens(appointment_id,patient_id,doctor_id,token) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,appointmentId);p.setLong(2,patientId);p.setLong(3,doctorId);p.setString(4,"PENDING-"+appointmentId);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();id=r.getLong(1);}}
            String token="Q"+String.format(Locale.ROOT,"%04d",id);try(PreparedStatement p=c.prepareStatement("UPDATE queue_tokens SET token=? WHERE id=?")){p.setString(1,token);p.setLong(2,id);p.executeUpdate();}c.commit();return queueToken(id,patientId,"PATIENT");
        }catch(SQLException|RuntimeException e){c.rollback();throw e;}}
    }
    public Map<String,Object> queueToken(long id,long actorId,String role) throws SQLException {try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT q.id,q.appointment_id,q.patient_id,q.doctor_id,q.token,q.status,q.issued_at,(SELECT COUNT(*) FROM queue_tokens prior WHERE prior.doctor_id=q.doctor_id AND prior.status='WAITING' AND prior.issued_at<q.issued_at) ahead FROM queue_tokens q WHERE q.id=? AND (?='ADMIN' OR (?='PATIENT' AND q.patient_id=?) OR (?='DOCTOR' AND q.doctor_id=?))")){p.setLong(1,id);p.setString(2,role);p.setString(3,role);p.setLong(4,actorId);p.setString(5,role);p.setLong(6,actorId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new NoSuchElementException("Queue token was not found.");Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getLong("id"));m.put("appointmentId",r.getLong("appointment_id"));m.put("token",r.getString("token"));m.put("status",r.getString("status"));m.put("peopleAhead",r.getInt("ahead"));m.put("estimatedWaitMinutes",r.getInt("ahead")*10);m.put("issuedAt",r.getTimestamp("issued_at").toLocalDateTime().toString());return m;}}}
    public List<Map<String,Object>> queueForDoctor(long doctorId) throws SQLException {List<Map<String,Object>> rows=new ArrayList<>();try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT id FROM queue_tokens WHERE doctor_id=? AND status='WAITING' ORDER BY issued_at")){p.setLong(1,doctorId);try(ResultSet r=p.executeQuery()){while(r.next())rows.add(queueToken(r.getLong(1),doctorId,"DOCTOR"));}}return rows;}
    public void updateQueue(long doctorId,long tokenId,String status) throws SQLException {if(!List.of("CALLED","SERVED").contains(status))throw new IllegalArgumentException("Queue status must be CALLED or SERVED.");try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE queue_tokens SET status=? WHERE id=? AND doctor_id=? AND status='WAITING'")){p.setString(1,status);p.setLong(2,tokenId);p.setLong(3,doctorId);if(p.executeUpdate()!=1)throw new NoSuchElementException("Waiting queue token was not found.");}}

    public List<Map<String,Object>> reminders(long patientId) throws SQLException {String sql="SELECT id,appointment_id,title,due_at,read_at FROM in_app_reminders WHERE user_id=? ORDER BY due_at DESC";List<Map<String,Object>> rows=new ArrayList<>();try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,patientId);try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getLong("id"));m.put("appointmentId",r.getLong("appointment_id"));m.put("title",r.getString("title"));m.put("dueAt",r.getTimestamp("due_at").toLocalDateTime().toString());m.put("read",r.getTimestamp("read_at")!=null);rows.add(m);}}}return rows;}
    public void generateReminders(long patientId) throws SQLException {String sql="SELECT id,appointment_date,appointment_time FROM appointments WHERE patient_id=? AND status='BOOKED' AND appointment_date>=?";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,patientId);p.setDate(2,Date.valueOf(LocalDate.now()));try(ResultSet r=p.executeQuery()){while(r.next()){long appt=r.getLong("id");LocalDateTime dt=LocalDateTime.of(r.getDate("appointment_date").toLocalDate(),r.getTime("appointment_time").toLocalTime()).minusHours(24);try(PreparedStatement i=c.prepareStatement("INSERT INTO in_app_reminders(user_id,appointment_id,reminder_type,title,due_at) VALUES(?,?,'APPOINTMENT','Upcoming appointment reminder',?)")){i.setLong(1,patientId);i.setLong(2,appt);i.setTimestamp(3,Timestamp.valueOf(dt));try{i.executeUpdate();}catch(SQLException duplicate){if(!"23505".equals(duplicate.getSQLState())&&duplicate.getErrorCode()!=1062)throw duplicate;}}}}}}
    public void markReminderRead(long patientId,long id) throws SQLException {try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE in_app_reminders SET read_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?")){p.setLong(1,id);p.setLong(2,patientId);if(p.executeUpdate()!=1)throw new NoSuchElementException("Reminder was not found.");}}
    public List<Map<String,Object>> timeline(long patientId) throws SQLException {List<Map<String,Object>> rows=new ArrayList<>();String appointments="SELECT id,appointment_date,status,appointment_time FROM appointments WHERE patient_id=?";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(appointments)){p.setLong(1,patientId);try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();m.put("type","APPOINTMENT");m.put("id",r.getLong("id"));m.put("date",r.getDate("appointment_date").toLocalDate().toString());m.put("title",r.getString("status"));m.put("detail",r.getTime("appointment_time").toLocalTime().toString());rows.add(m);}}}String visits="SELECT c.id,a.appointment_date,c.diagnosis,a.appointment_time FROM consultations c JOIN appointments a ON a.id=c.appointment_id WHERE c.patient_id=?";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(visits)){p.setLong(1,patientId);try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();m.put("type","CONSULTATION");m.put("id",r.getLong("id"));m.put("date",r.getDate("appointment_date").toLocalDate().toString());m.put("title","Visit completed");m.put("detail",r.getString("diagnosis")+" · "+r.getTime("appointment_time").toLocalTime());rows.add(m);}}}rows.sort((a,b)->String.valueOf(b.get("date")).compareTo(String.valueOf(a.get("date"))));return rows;}

    private int medicineStock(Connection c,long medicineId)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT stock FROM medicines WHERE id=?")){p.setLong(1,medicineId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new NoSuchElementException("Medicine was not found.");return r.getInt(1);}}}
    private long ensureCart(long patient) throws SQLException {try(Connection c=Database.getConnection()){return ensureCart(c,patient);}}
    private long ensureCart(Connection c,long patient) throws SQLException {try(PreparedStatement q=c.prepareStatement("SELECT id FROM patient_carts WHERE patient_id=?")){q.setLong(1,patient);try(ResultSet r=q.executeQuery()){if(r.next())return r.getLong(1);}}try(PreparedStatement i=c.prepareStatement("INSERT INTO patient_carts(patient_id) VALUES(?)",Statement.RETURN_GENERATED_KEYS)){i.setLong(1,patient);i.executeUpdate();try(ResultSet r=i.getGeneratedKeys()){if(!r.next())throw new SQLException("Cart id missing.");return r.getLong(1);}}}
    private Map<String,Object> order(long id) throws SQLException {String sql="SELECT id,patient_id,order_number,total,status,created_at FROM medicine_orders WHERE id=?";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new NoSuchElementException("Order was not found.");Map<String,Object> m=orderRow(r);m.put("items",orderItems(c,id));return m;}}}
    private Map<String,Object> orderRow(ResultSet r)throws SQLException{Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getLong("id"));m.put("patientId",r.getLong("patient_id"));m.put("orderNumber",r.getString("order_number"));m.put("total",r.getBigDecimal("total"));m.put("status",r.getString("status"));m.put("createdAt",r.getTimestamp("created_at").toLocalDateTime().toString());return m;}
    private List<Map<String,Object>> orderItems(Connection c,long id)throws SQLException{List<Map<String,Object>> out=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT medicine_name,unit_price,quantity FROM medicine_order_items WHERE order_id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();m.put("name",r.getString(1));m.put("unitPrice",r.getBigDecimal(2));m.put("quantity",r.getInt(3));out.add(m);}}}return out;}
    private List<Map<String,Object>> prescriptionItems(Connection c,long id)throws SQLException{List<Map<String,Object>> out=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT medicine_id,medicine_name,dosage,quantity FROM prescription_items WHERE prescription_id=? ORDER BY id")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();long medicine=r.getLong("medicine_id");m.put("medicineId",r.wasNull()?null:medicine);m.put("medicineName",r.getString("medicine_name"));m.put("dosage",r.getString("dosage"));m.put("quantity",r.getInt("quantity"));out.add(m);}}}return out;}
    public static final class PrescriptionLine {public final long medicineId;public final String name,dosage;public final int quantity;public PrescriptionLine(long medicineId,String name,String dosage,int quantity){this.medicineId=medicineId;this.name=name;this.dosage=dosage;this.quantity=quantity;}}
    private static final class OrderLine {final long medicineId;final String name;final int quantity;final BigDecimal price;OrderLine(long id,String name,int q,BigDecimal price){medicineId=id;this.name=name;quantity=q;this.price=price;}}
}
